class Solution:
    def sequentialGridPathCover(self, grid, k):
        m, n = len(grid), len(grid[0])
        visited = [[False] * n for _ in range(m)]
        path = []
        dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

        def dfs(i, j, exp):
            v = grid[i][j]
            if v != 0 and v != exp:
                return False
            ne = exp + 1 if v == exp else exp
            visited[i][j] = True
            path.append([i, j])
            if len(path) == m * n:
                return True
            for di, dj in dirs:
                a, b = i + di, j + dj
                if 0 <= a < m and 0 <= b < n and not visited[a][b]:
                    if dfs(a, b, ne):
                        return True
            visited[i][j] = False
            path.pop()
            return False

        for i in range(m):
            for j in range(n):
                if dfs(i, j, 1):
                    return path
        return []

