class Solution {
public:
    vector<vector<int>> sequentialGridPathCover(vector<vector<int>>& grid, int k) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<bool>> vis(m, vector<bool>(n, false));
        vector<vector<int>> path;
        int dr[] = {1, -1, 0, 0}, dc[] = {0, 0, 1, -1};
        function<bool(int,int,int)> dfs = [&](int i, int j, int exp) -> bool {
            int v = grid[i][j];
            if (v != 0 && v != exp) return false;
            int ne = (v == exp) ? exp + 1 : exp;
            vis[i][j] = true;
            path.push_back({i, j});
            if ((int)path.size() == m * n) return true;
            for (int d = 0; d < 4; d++) {
                int a = i + dr[d], b = j + dc[d];
                if (a >= 0 && a < m && b >= 0 && b < n && !vis[a][b] && dfs(a, b, ne)) return true;
            }
            vis[i][j] = false;
            path.pop_back();
            return false;
        };
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (dfs(i, j, 1)) return path;
        return {};
    }
};

