class Solution {
    int m, n;
    int[][] grid;
    boolean[][] vis;
    List<int[]> path = new ArrayList<>();
    int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};

    public int[][] sequentialGridPathCover(int[][] g, int k) {
        grid = g; m = grid.length; n = grid[0].length;
        vis = new boolean[m][n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (dfs(i, j, 1)) {
                    int[][] res = new int[path.size()][];
                    for (int t = 0; t < path.size(); t++) res[t] = path.get(t);
                    return res;
                }
        return new int[0][];
    }

    private boolean dfs(int i, int j, int exp) {
        int v = grid[i][j];
        if (v != 0 && v != exp) return false;
        int ne = (v == exp) ? exp + 1 : exp;
        vis[i][j] = true;
        path.add(new int[]{i, j});
        if (path.size() == m * n) return true;
        for (int d = 0; d < 4; d++) {
            int a = i + dr[d], b = j + dc[d];
            if (a >= 0 && a < m && b >= 0 && b < n && !vis[a][b] && dfs(a, b, ne)) return true;
        }
        vis[i][j] = false;
        path.remove(path.size() - 1);
        return false;
    }
}

