var sequentialGridPathCover = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const vis = Array.from({length: m}, () => Array(n).fill(false));
    const path = [];
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    function dfs(i, j, exp) {
        const v = grid[i][j];
        if (v !== 0 && v !== exp) return false;
        const ne = v === exp ? exp + 1 : exp;
        vis[i][j] = true;
        path.push([i, j]);
        if (path.length === m * n) return true;
        for (const [di, dj] of dirs) {
            const a = i + di, b = j + dj;
            if (a >= 0 && a < m && b >= 0 && b < n && !vis[a][b] && dfs(a, b, ne)) return true;
        }
        vis[i][j] = false;
        path.pop();
        return false;
    }
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++)
            if (dfs(i, j, 1)) return path;
    return [];
};
